using System.Globalization;

if (args.Length == 0)
{
    Console.WriteLine("使い方: dotnet run -- 食費:500 食費:800 交通費:200");
    return 0;
}
if (args.Length > 1000)
{
    Console.Error.WriteLine("1回に指定できる支出は1000件までです。");
    return 1;
}
var expenses = new List<Expense>();
foreach (string arg in args)
{
    int separator = arg.LastIndexOf(':');
    if (separator <= 0 || separator == arg.Length - 1)
    {
        Console.Error.WriteLine($"形式が不正です: {arg}（カテゴリ:金額で指定）");
        return 1;
    }
    string category = arg[..separator].Trim();
    string amountText = arg[(separator + 1)..];
    if (category.Length is < 1 or > 40 ||
        !decimal.TryParse(amountText, NumberStyles.AllowDecimalPoint,
            CultureInfo.InvariantCulture, out decimal amount) ||
        amount <= 0m || amount > 1_000_000_000m ||
        decimal.Round(amount, 2) != amount)
    {
        Console.Error.WriteLine($"入力が不正です: {arg}（カテゴリ1〜40文字、金額0超〜10億、小数2桁以内）");
        return 1;
    }
    expenses.Add(new Expense(category, amount));
}
foreach (var group in expenses.GroupBy(x => x.Category).OrderBy(g => g.Key, StringComparer.Ordinal))
    Console.WriteLine($"{group.Key}: {Format(group.Sum(x => x.Amount))}円");
Console.WriteLine($"合計: {Format(expenses.Sum(x => x.Amount))}円");
return 0;

static string Format(decimal value) => value.ToString("0.##", CultureInfo.InvariantCulture);
public record Expense(string Category, decimal Amount);

using System.Text.Json;

string root = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
    "CSharpLearningLab");
string path = Path.Combine(root, "tasks.json");
string command = args.FirstOrDefault()?.ToLowerInvariant() ?? "help";
if (command == "where") { Console.WriteLine(path); return 0; }
if (command == "help")
{
    Console.WriteLine("コマンド: list / add \"タイトル\" / done ID / delete ID / where");
    return 0;
}
if (command is not ("list" or "add" or "done" or "delete"))
{
    Console.Error.WriteLine("不明なコマンドです。引数なしで使い方を表示します。");
    return 1;
}
try
{
    List<TaskItem> tasks = Load(path);
    switch (command)
    {
        case "list":
            if (args.Length != 1) throw new ArgumentException("listに追加の引数は不要です。");
            foreach (var item in tasks.OrderBy(x => x.CreatedAt))
                Console.WriteLine($"[{(item.Done ? "x" : " ")}] {item.Id} {item.Title}");
            Console.WriteLine($"{tasks.Count}件 / 完了{tasks.Count(x => x.Done)}件");
            return 0;
        case "add":
            if (args.Length != 2 || string.IsNullOrWhiteSpace(args[1]) || args[1].Trim().Length > 100)
                throw new ArgumentException("タイトルは1〜100文字。空白を含む場合は引用符で囲んでください。");
            if (tasks.Count >= 1000) throw new ArgumentException("タスクは1000件までです。");
            var added = new TaskItem(Guid.NewGuid(), args[1].Trim(), false, DateTimeOffset.UtcNow);
            tasks.Add(added);
            Save(path, tasks);
            Console.WriteLine($"追加: {added.Id} {added.Title}");
            return 0;
        default:
            if (args.Length != 2 || !Guid.TryParse(args[1], out Guid id))
                throw new ArgumentException("listに表示された有効なIDを指定してください。");
            int index = tasks.FindIndex(x => x.Id == id);
            if (index < 0) throw new ArgumentException("対象のタスクがありません。");
            if (command == "done") tasks[index] = tasks[index] with { Done = true };
            else tasks.RemoveAt(index);
            Save(path, tasks);
            Console.WriteLine(command == "done" ? "完了にしました。" : "削除しました。");
            return 0;
    }
}
catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or JsonException or ArgumentException)
{
    Console.Error.WriteLine($"処理を中断しました: {ex.Message}");
    Console.Error.WriteLine($"保存先: {path}");
    return 1;
}

static List<TaskItem> Load(string path)
{
    string json;
    try { json = File.ReadAllText(path); }
    catch (FileNotFoundException) { return new List<TaskItem>(); }
    catch (DirectoryNotFoundException) { return new List<TaskItem>(); }
    if (json.Length > 2_000_000) throw new JsonException("保存データが大きすぎます。");
    var tasks = JsonSerializer.Deserialize<List<TaskItem>>(json)
        ?? throw new JsonException("保存データがnullです。初期化せず中断します。");
    if (tasks.Count > 1000 || tasks.Any(x => x is null || x.Id == Guid.Empty ||
        string.IsNullOrWhiteSpace(x.Title) || x.Title.Length > 100 || x.CreatedAt == default) ||
        tasks.Select(x => x.Id).Distinct().Count() != tasks.Count)
        throw new JsonException("保存データの内容に不正があります。初期化せず中断します。");
    return tasks;
}
static void Save(string path, List<TaskItem> tasks)
{
    Directory.CreateDirectory(Path.GetDirectoryName(path)!);
    string temporary = path + "." + Guid.NewGuid().ToString("N") + ".tmp";
    try
    {
        File.WriteAllText(temporary, JsonSerializer.Serialize(tasks,
            new JsonSerializerOptions { WriteIndented = true }));
        // 同一ディレクトリの一時ファイルから置き換える。複数プロセスの排他制御ではない。
        File.Move(temporary, path, overwrite: true);
    }
    finally
    {
        if (File.Exists(temporary)) File.Delete(temporary);
    }
}
public record TaskItem(Guid Id, string Title, bool Done, DateTimeOffset CreatedAt);

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<TaskStore>();
builder.Services.AddProblemDetails();
var app = builder.Build();
app.UseExceptionHandler();
app.MapGet("/health", () => Results.Ok(new { status = "ok" }));
app.MapGet("/tasks", (TaskStore store) => Results.Ok(store.All()));
app.MapGet("/tasks/{id:int}", GetTask);
app.MapPost("/tasks", CreateTask);
app.MapPut("/tasks/{id:int}/complete", CompleteTask);
app.MapDelete("/tasks/{id:int}", DeleteTask);
app.Run("http://127.0.0.1:5080");

static IResult GetTask(int id, TaskStore store)
{
    var task = store.Find(id);
    return task is null ? Results.NotFound() : Results.Ok(task);
}
static IResult CreateTask(CreateTaskRequest input, TaskStore store)
{
    if (string.IsNullOrWhiteSpace(input.Title) || input.Title.Trim().Length > 100)
        return Results.BadRequest(new { error = "タイトルは1〜100文字です。" });
    var task = store.Add(input.Title.Trim());
    return task is null
        ? Results.Conflict(new { error = "登録できるタスク数の上限に達しました。" })
        : Results.Created($"/tasks/{task.Id}", task);
}
static IResult CompleteTask(int id, TaskStore store)
{
    var task = store.Complete(id);
    return task is null ? Results.NotFound() : Results.Ok(task);
}
static IResult DeleteTask(int id, TaskStore store)
    => store.Delete(id) ? Results.NoContent() : Results.NotFound();

public record CreateTaskRequest(string? Title);
public record TaskItem(int Id, string Title, bool Done);
public sealed class TaskStore
{
    private readonly object gate = new();
    private readonly Dictionary<int, TaskItem> tasks = new();
    private int nextId;
    public TaskItem[] All()
    {
        lock (gate) return tasks.Values.OrderBy(x => x.Id).ToArray();
    }
    public TaskItem? Find(int id)
    {
        lock (gate) return tasks.GetValueOrDefault(id);
    }
    public TaskItem? Add(string title)
    {
        lock (gate)
        {
            if (tasks.Count >= 1000 || nextId == int.MaxValue) return null;
            var task = new TaskItem(++nextId, title, false);
            tasks.Add(task.Id, task);
            return task;
        }
    }
    public TaskItem? Complete(int id)
    {
        lock (gate)
        {
            if (!tasks.TryGetValue(id, out var task)) return null;
            return tasks[id] = task with { Done = true };
        }
    }
    public bool Delete(int id)
    {
        lock (gate) return tasks.Remove(id);
    }
}
